    var state={configured:false,user:null,filter:'all',tag:null,query:'',sort:'latest',discussions:[],active:null,authMode:'login'};
    var $=function(s){return document.querySelector(s)}, $$=function(s){return Array.prototype.slice.call(document.querySelectorAll(s))};
    function esc(v){return String(v==null?'':v).replace(/[&<>'"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]})}
    function initials(n){return String(n||'Thành viên').split(/\s+/).slice(-2).map(function(x){return x[0]}).join('').toUpperCase()}
    function toast(msg,bad){var e=document.createElement('div');e.className='toast'+(bad?' bad':'');e.textContent=msg;$('#toasts').appendChild(e);setTimeout(function(){e.remove()},3200)}
    function savedDemo(){try{return JSON.parse(localStorage.getItem('community_discussions')||'null')}catch(e){return null}}
    function persist(){if(!state.configured)localStorage.setItem('community_discussions',JSON.stringify(state.discussions))}
    async function api(path,opts){opts=opts||{};var token=localStorage.getItem('community_token');opts.headers=Object.assign({'content-type':'application/json'},opts.headers||{},token?{authorization:'Bearer '+token}:{});var r=await fetch(path,opts);var data=await r.json().catch(function(){return {error:'Phản hồi không hợp lệ'}});if(!r.ok)throw new Error(data.error||data.msg||data.message||'Có lỗi xảy ra');return data}
    function normalizeRemote(d){var p=d.profiles||{},dt=d.discussion_tags&&d.discussion_tags[0]&&d.discussion_tags[0].tags;return {id:d.id,title:d.title,excerpt:(d.content||'').slice(0,150),content:d.content||'',author:{name:p.display_name||p.username||'Thành viên',username:p.username||'',initials:initials(p.display_name||p.username),color:p.avatar_color||'#6c5ce7'},tag:dt||tags[1],created:new Date(d.created_at).toLocaleDateString('vi-VN'),updated:new Date(d.updated_at).getTime(),replies:d.reply_count||0,views:d.view_count||0,pinned:d.is_pinned||false,following:false,posts:[]}}
    async function boot(){var config=await api('/api/config').catch(function(){return {configured:false}});state.configured=!!config.configured;$('#backendStatus').textContent=state.configured?'Đã kết nối Supabase':'Chế độ demo · Chờ Supabase';if(state.configured){var me=await api('/api/me').catch(function(){localStorage.removeItem('community_token');return null});if(me&&me.user)setUser(me.user);var remote=await api('/api/discussions').catch(function(){toast('Không đọc được bảng Supabase, đang dùng dữ liệu mẫu',true);return null});state.discussions=remote&&remote.discussions?remote.discussions.map(normalizeRemote):(savedDemo()||demoDiscussions)}else state.discussions=savedDemo()||demoDiscussions;renderTags();render()}
    function renderTags(){$('#tagNav').innerHTML=tags.map(function(t){return '<button class="nav-item" data-tag="'+t.slug+'"><span class="tag-dot" style="background:'+t.color+'"></span>'+esc(t.name)+'</button>'}).join('');$$('[data-tag]').forEach(function(b){b.onclick=function(){state.tag=b.dataset.tag;state.filter='tag';$('#feedTitle').textContent=tags.find(function(t){return t.slug===state.tag}).name;markNav();render()}})}
    function markNav(){$$('.nav-item').forEach(function(x){x.classList.toggle('active',(x.dataset.filter&&x.dataset.filter===state.filter)||(x.dataset.tag&&x.dataset.tag===state.tag))})}
    function filtered(){var list=state.discussions.slice();if(state.filter==='following')list=list.filter(function(d){return d.following});if(state.filter==='unanswered')list=list.filter(function(d){return !d.replies});if(state.filter==='popular')list=list.filter(function(d){return d.views>300||d.replies>20});if(state.filter==='tag')list=list.filter(function(d){return d.tag&&d.tag.slug===state.tag});if(state.query){var q=state.query.toLowerCase();list=list.filter(function(d){return d.title.toLowerCase().includes(q)||(d.excerpt||'').toLowerCase().includes(q)})}list.sort(function(a,b){if(a.pinned!==b.pinned)return a.pinned?-1:1;if(state.sort==='top')return (b.views+b.replies*8)-(a.views+a.replies*8);return b.updated-a.updated});return list}
    function discussionHtml(d){return '<article class="discussion"><span class="avatar" style="background:'+esc(d.author.color)+'">'+esc(d.author.initials)+'</span><div class="discussion-main"><h2 class="d-title" data-open="'+esc(d.id)+'">'+(d.pinned?'<span class="pinned">Ghim</span>':'')+esc(d.title)+'</h2><div class="d-excerpt">'+esc(d.excerpt)+'</div><div class="meta"><b>'+esc(d.author.name)+'</b><span>'+esc(d.created)+'</span><span class="tag"><i class="tag-dot" style="background:'+esc(d.tag.color)+'"></i>'+esc(d.tag.name)+'</span></div></div><div class="stats"><div class="stat"><strong>'+d.replies+'</strong>trả lời</div><div class="stat"><strong>'+d.views+'</strong>lượt xem</div></div></article>'}
    function render(){var list=filtered();$('#allCount').textContent=state.discussions.length;$('#discussionList').innerHTML=list.length?list.map(discussionHtml).join(''):'<div class="empty"><div class="empty-icon">⌕</div><b>Chưa có thảo luận phù hợp</b><p>Hãy thử từ khóa hoặc bộ lọc khác.</p></div>';$$('[data-open]').forEach(function(x){x.onclick=function(){openDiscussion(x.dataset.open)}});var trend=state.discussions.slice().sort(function(a,b){return b.views-a.views}).slice(0,3);$('#trending').innerHTML=trend.map(function(d,i){return '<div class="trend"><span class="trend-num">'+(i+1)+'</span><div><div class="trend-title">'+esc(d.title)+'</div><div class="trend-meta">'+d.replies+' trả lời · '+d.views+' lượt xem</div></div></div>'}).join('')}
    async function openDiscussion(id){var d=state.discussions.find(function(x){return String(x.id)===String(id)});if(!d)return;if(state.configured&&!d.posts.length){var remote=await api('/api/discussions/'+id).catch(function(){return null});if(remote&&remote.posts)d.posts=remote.posts.map(function(p){var u=p.profiles||{};return {id:p.id,author:{name:u.display_name||u.username||'Thành viên',initials:initials(u.display_name||u.username),color:u.avatar_color||'#6c5ce7'},time:new Date(p.created_at).toLocaleString('vi-VN'),content:p.content,likes:p.like_count||0}})}state.active=d;d.views++;var posts=d.posts.length?d.posts:[{id:'root-'+d.id,author:d.author,time:d.created,content:d.content,likes:0}];$('#detail').innerHTML='<div class="detail-top"><div class="detail-top-inner"><button class="back" id="backBtn">←</button><div class="detail-title">'+esc(d.title)+'</div><button class="btn" id="followBtn">'+(d.following?'Đang theo dõi':'Theo dõi')+'</button></div></div><div class="detail-body"><section class="detail-hero"><span class="tag"><i class="tag-dot" style="background:'+d.tag.color+'"></i>'+esc(d.tag.name)+'</span><h1>'+esc(d.title)+'</h1><div class="detail-meta">Bắt đầu bởi '+esc(d.author.name)+' · '+esc(d.created)+' · '+d.views+' lượt xem</div></section>'+posts.map(function(p,i){return '<article class="post"><div class="post-head"><span class="avatar" style="background:'+p.author.color+'">'+esc(p.author.initials)+'</span><div><div class="post-author">'+esc(p.author.name)+'</div><div class="post-time">'+esc(p.time)+'</div></div><span class="post-number">#'+(i+1)+'</span></div><div class="post-content">'+esc(p.content)+'</div><div class="post-actions"><button class="text-btn" data-like="'+esc(p.id)+'">♡ Thích <span>'+p.likes+'</span></button><button class="text-btn" data-quote="'+esc(p.author.name)+'">↩ Trả lời</button></div></article>'}).join('')+'<div class="reply-box"><span class="avatar">'+(state.user?esc(initials(state.user.name||state.user.email)):'?')+'</span><button class="reply-placeholder" id="replyBtn">Viết câu trả lời...</button></div></div>';$('#detail').classList.remove('hidden');document.body.style.overflow='hidden';$('#backBtn').onclick=closeDetail;$('#followBtn').onclick=function(){d.following=!d.following;this.textContent=d.following?'Đang theo dõi':'Theo dõi';persist();toast(d.following?'Đã theo dõi thảo luận':'Đã bỏ theo dõi')};$('#replyBtn').onclick=function(){requireAuth(function(){openReply()})};$$('[data-like]').forEach(function(b){b.onclick=function(){var p=d.posts.find(function(x){return String(x.id)===String(b.dataset.like)})||posts.find(function(x){return String(x.id)===String(b.dataset.like)});p.likes++;b.classList.add('liked');b.innerHTML='♥ Đã thích <span>'+p.likes+'</span>';persist()}});$$('[data-quote]').forEach(function(b){b.onclick=function(){requireAuth(function(){openReply('@'+b.dataset.quote+' ')})}})}
    function closeDetail(){$('#detail').classList.add('hidden');document.body.style.overflow='';state.active=null;render()}
    function openReply(prefix){modal('Trả lời thảo luận','<div class="field"><label>Nội dung</label><textarea id="replyContent" placeholder="Chia sẻ suy nghĩ của bạn...">'+esc(prefix||'')+'</textarea></div><div class="modal-actions"><button class="btn" data-close>Hủy</button><button class="btn btn-primary" id="submitReply">Đăng trả lời</button></div>','wide');setTimeout(function(){$('#replyContent').focus()},0);$('#submitReply').onclick=submitReply}
    async function submitReply(){var content=$('#replyContent').value.trim();if(!content)return toast('Vui lòng nhập nội dung',true);var d=state.active;try{if(state.configured)await api('/api/discussions/'+d.id+'/posts',{method:'POST',body:JSON.stringify({content:content})});var user=state.user||{name:'Bạn'};d.posts.push({id:'p'+Date.now(),author:{name:user.name||user.email,initials:initials(user.name||user.email),color:'#6c5ce7'},time:'Vừa xong',content:content,likes:0});d.replies++;d.updated=Date.now();persist();closeModal();openDiscussion(d.id);toast('Đã đăng câu trả lời')}catch(e){toast(e.message,true)}}
    function modal(title,body,klass){$('#overlay').innerHTML='<div class="modal-backdrop"><div class="modal '+(klass||'')+'"><div class="modal-head"><h2>'+esc(title)+'</h2><button class="close" data-close>×</button></div><div class="modal-body">'+body+'</div></div></div>';$$('[data-close]').forEach(function(x){x.onclick=closeModal});$('.modal-backdrop').onclick=function(e){if(e.target===this)closeModal()}}
    function closeModal(){$('#overlay').innerHTML=''}
    function openComposer(){requireAuth(function(){modal('Bắt đầu thảo luận','<div class="field"><label>Tiêu đề</label><input id="newTitle" maxlength="140" placeholder="Bạn muốn thảo luận điều gì?"></div><div class="field"><label>Chủ đề</label><select id="newTag">'+tags.map(function(t){return '<option value="'+t.slug+'">'+esc(t.name)+'</option>'}).join('')+'</select></div><div class="field"><label>Nội dung</label><textarea id="newContent" placeholder="Mô tả chi tiết để mọi người dễ tham gia..."></textarea></div><div class="modal-actions"><button class="btn" data-close>Hủy</button><button class="btn btn-primary" id="submitDiscussion">Đăng thảo luận</button></div>','wide');$('#submitDiscussion').onclick=submitDiscussion})}
    async function submitDiscussion(){var title=$('#newTitle').value.trim(),content=$('#newContent').value.trim(),tag=tags.find(function(t){return t.slug===$('#newTag').value});if(title.length<6||content.length<10)return toast('Tiêu đề hoặc nội dung còn quá ngắn',true);try{var created=null;if(state.configured)created=await api('/api/discussions',{method:'POST',body:JSON.stringify({title:title,content:content,tag_id:tag.id||null})});var user=state.user||{name:'Bạn'};var d=created&&created.discussion?normalizeRemote(created.discussion):{id:'d'+Date.now(),title:title,excerpt:content.slice(0,150),content:content,author:{name:user.name||user.email,initials:initials(user.name||user.email),color:'#6c5ce7'},tag:tag,created:'Vừa xong',updated:Date.now(),replies:0,views:0,pinned:false,following:true,posts:[]};state.discussions.unshift(d);persist();closeModal();render();toast('Thảo luận đã được đăng')}catch(e){toast(e.message,true)}}
    function requireAuth(fn){if(state.user)return fn();openAuth(fn)}
    function openAuth(after){state.authMode='login';var demoNote=state.configured?'Tài khoản được xác thực an toàn qua Supabase.':'Site đang ở chế độ demo. Bạn có thể đăng nhập bằng email bất kỳ để thử giao diện.';modal('Tham gia cộng đồng','<div class="auth-tabs"><button class="auth-tab active" data-auth="login">Đăng nhập</button><button class="auth-tab" data-auth="signup">Đăng ký</button></div><div class="notice">'+demoNote+'</div><div class="field signup-only hidden"><label>Tên hiển thị</label><input id="authName" placeholder="Nguyễn Văn A"></div><div class="field"><label>Email</label><input id="authEmail" type="email" placeholder="ban@example.com"></div><div class="field"><label>Mật khẩu</label><input id="authPass" type="password" placeholder="Tối thiểu 6 ký tự"></div><div id="authError"></div><button class="btn btn-primary" style="width:100%" id="authSubmit">Tiếp tục</button><p class="help" style="text-align:center">Bằng việc tiếp tục, bạn đồng ý tuân thủ quy tắc cộng đồng.</p>');$$('[data-auth]').forEach(function(b){b.onclick=function(){state.authMode=b.dataset.auth;$$('[data-auth]').forEach(function(x){x.classList.toggle('active',x===b)});$$('.signup-only').forEach(function(x){x.classList.toggle('hidden',state.authMode!=='signup')})}});$('#authSubmit').onclick=async function(){var email=$('#authEmail').value.trim(),pass=$('#authPass').value,name=$('#authName')?$('#authName').value.trim():'';if(!email||pass.length<6)return showAuthError('Hãy nhập email và mật khẩu tối thiểu 6 ký tự.');try{if(state.configured){var out=await api('/api/auth/'+state.authMode,{method:'POST',body:JSON.stringify({email:email,password:pass,name:name})});if(out.access_token)localStorage.setItem('community_token',out.access_token);if(state.authMode==='signup'&&!out.access_token){toast('Hãy kiểm tra email để xác nhận tài khoản');closeModal();return}var me=await api('/api/me');setUser(me.user)}else setUser({email:email,name:name||email.split('@')[0]});closeModal();toast('Đăng nhập thành công');if(after)after()}catch(e){showAuthError(e.message)}}}
    function showAuthError(s){$('#authError').innerHTML='<div class="notice error">'+esc(s)+'</div>'}
    function setUser(u){state.user={id:u.id,email:u.email,name:(u.user_metadata&&u.user_metadata.display_name)||u.name||u.email,role:u.role||(u.profile&&u.profile.role)||'member'};$('#loginBtn').classList.add('hidden');$('#userBtn').classList.remove('hidden');$('#topAvatar').textContent=initials(state.user.name)}
